"""Calls a flaky service."""
import time


class TransientError(Exception):
    """A failure worth retrying, such as a timeout."""


def fetch_with_retry(call, sleep=time.sleep, attempts=3, base_delay=0.5):
    """Return the result of `call()`, retrying TransientError up to `attempts` calls with exponential backoff."""
    for attempt in range(attempts):
        try:
            return call()
        except TransientError:
            if attempt == attempts - 1:
                raise
            sleep(base_delay * (attempt + 1))

import unittest

from client import TransientError, fetch_with_retry


class RetryTest(unittest.TestCase):
    def test_retries_until_success(self):
        calls, delays = [], []

        def flaky():
            calls.append(1)
            if len(calls) < 3:
                raise TransientError("try again")
            return "done"

        self.assertEqual(fetch_with_retry(flaky, sleep=delays.append), "done")
        self.assertEqual(len(calls), 3)
